input.script:
(() => {
  const q = s => document.querySelector(s);
  const banner = q('.page-status, .unresolved-incidents, .status-description');
  const overall = Array.from(document.querySelectorAll('.page-status .status, .page-status, .unresolved-incident')).map(e => e.innerText.trim()).filter(Boolean);
  const comps = Array.from(document.querySelectorAll('.component-inner-container')).map(c => {
    const name = c.querySelector('.name')?.innerText.trim();
    const status = c.querySelector('.component-status')?.innerText.trim();
    return name + ': ' + status;
  });
  const incidents = Array.from(document.querySelectorAll('.unresolved-incidents .incident-title, .unresolved-incident .incident-title')).map(e => e.innerText.trim());
  return JSON.stringify({title: document.title, overall, incidents, comps}, null, 1);
})()
